import { COMPONENTS } from "@/lib/framework";

/** Hand-written embedded developer scenarios, not generated by AI. */
const embedded = [
  [
    "Ask a teammate which sensor behaviour the requester expects, then repeat it back.",
    "Interview the product owner independently and clarify when a missing reading becomes a real problem.",
    "Resolve conflicting needs between firmware and product teams during an unfamiliar field incident.",
  ],
  [
    "Show a simple retry proposal and explain its benefit with a colleague\u2019s help.",
    "Compare two firmware fixes, recommend one and answer questions about latency and reliability.",
    "Defend a revised sensor design when product and hardware stakeholders disagree about the trade-offs.",
  ],
  [
    "Find the relevant coding rule with a reviewer and apply it to a small change.",
    "Identify the coding and interface requirements yourself and refuse a shortcut that violates them.",
    "Resolve an ambiguous requirement for a new device and document the interpretation others can follow.",
  ],
  [
    "Run the supplied sensor test checklist with a colleague. Spot an incorrect reading and record it.",
    "Write and run tests for normal readings, disconnects and timeouts. Find a missing error case in a peer\u2019s patch.",
    "Design the team\u2019s checks for intermittent faults across device versions. Catch a timing problem that ordinary tests missed.",
  ],
  [
    "Break a small sensor fix into three tasks with guidance.",
    "Define the fix\u2019s scope, tests and handover, then flag a delay before it affects delivery.",
    "Replan a device release across firmware and hardware teams when requirements change.",
  ],
  [
    "After fixing a sensor issue, describe what worked and one thing to change.",
    "Write a short troubleshooting guide from the fix and share it with the next developer.",
    "Turn recurring device failures into a review practice used across the team.",
  ],
  [
    "Contribute a small firmware change, listen to feedback and keep a teammate informed.",
    "Coordinate an interface change with the hardware developer and unblock a teammate.",
    "Help firmware and hardware teams work through conflicting priorities during a difficult release.",
  ],
  [
    "Explain why you chose a polling interval and recognise a better option after feedback.",
    "Notice your initial assumption about sensor timing was wrong and change your investigation.",
    "Challenge your debugging strategy before a novel device issue derails the team, and help peers reflect too.",
  ],
  [
    "Finish the agreed sensor check on time and volunteer to document the result.",
    "Own a firmware fix through testing and handover, and propose a useful follow-up.",
    "Take responsibility for an intermittent field fault nobody owns and coordinate it through resolution.",
  ],
  [
    "With help, turn \u201cthe sensor is unreliable\u201d into a clear symptom and list assumptions.",
    "Independently turn vague reports into a reproducible problem with boundaries and evidence.",
    "Create a shared problem statement when several teams disagree about a new class of failures.",
  ],
  [
    "Use an unfamiliar device guide to complete a small check with help.",
    "Learn an unfamiliar sensor interface independently and use it in the prototype.",
    "Master a new device platform deeply enough to guide the team through difficult cases.",
  ],
  [
    "Write a clear test update and explain the result to a teammate.",
    "Write an incident report for support colleagues and lead a discussion of the fix.",
    "Explain a complex release failure to technical and non-technical stakeholders under pressure.",
  ],
];
export function jobScenario(
  code: string,
  level: 1 | 2 | 3,
  title: string,
): string | undefined {
  if (!/embedded|firmware|embarqué/i.test(title)) return undefined;
  const index = COMPONENTS.findIndex((c) => c.code === code);
  return embedded[index]?.[level - 1];
}
